<script lang="ts">
 import {onMount} from 'svelte';import {api} from '#lib/api.ts';import {session} from '#lib/session.svelte.ts';import {t} from '#lib/i18n/index.svelte.ts';import PageHead from '#lib/components/PageHead.svelte';import Dialog from '#lib/components/Dialog.svelte';import EmptyState from '#lib/components/EmptyState.svelte';import {formatBytes} from '#lib/format.ts';import {operationError} from '#lib/operations.ts';
 type Candidate={id:string;filesystem:string;filesystemUUID:string;arrayUUID:string;level:string;disks:string[];size:number;fingerprint:string;reason:string};type Preview={candidate:Candidate;folders:string[];truncated:boolean;readOnly:boolean};
 const admin=$derived(['owner','admin'].includes(session.data?.user?.role??''));let list=$state<Candidate[]>([]),preview=$state<Preview|null>(null),name=$state(''),confirm=$state(''),busy=$state(false),error=$state(''),registered=$state('');
 async function load(){busy=true;error='';try{list=await api.get('/storage/import');}catch(e){error=operationError(e,t);}finally{busy=false;}}
 onMount(()=>{if(admin)load();});
 async function inspect(c:Candidate){busy=true;error='';try{preview=await api.post('/storage/import/preview',{id:c.id,fingerprint:c.fingerprint});name='';confirm='';}catch(e){error=operationError(e,t);}finally{busy=false;}}
 async function register(){if(!preview)return;busy=true;error='';try{await api.post('/storage/import',{id:preview.candidate.id,fingerprint:preview.candidate.fingerprint,name,confirm});registered=name;preview=null;await load();}catch(e){error=operationError(e,t);}finally{busy=false;}}
</script>
{#if admin}<PageHead title={t('ops.import')} parent={{href:'/storage',label:t('nav.storage')}}>{#snippet actions()}<button class="btn" disabled={busy} onclick={load}>{t('ops.refresh')}</button>{/snippet}</PageHead><p class="muted">{t('ops.importHint')}</p>
{#if error}<p class="notice-error" role="alert">{error}</p>{/if}{#if registered}<p class="notice" role="status"><a href="/storage">{registered} →</a></p>{/if}
<section class="tile candidates">{#each list as c(c.id)}<article><div><strong>{c.level} · {c.filesystem.toUpperCase()}</strong><p class="mono">{c.id}</p><p>{c.disks.join(' · ')} · {formatBytes(c.size)}</p>{#if c.reason}<p class="notice-warn">{c.reason}</p>{/if}</div><button class="btn btn-primary" disabled={busy||!!c.reason} onclick={()=>inspect(c)}>{t('ops.preview')}</button></article>{:else}<EmptyState inline title={busy?t('ops.loading'):t('ops.importNone')}/>{/each}</section>
{#if preview}<Dialog title={t('ops.import')} locked={busy} onclose={()=>preview=null}><p>{t('ops.importReady')}</p><p class="mono">{preview.candidate.filesystemUUID}</p><h3>{t('ops.folders')}</h3><ul>{#each preview.folders as folder(folder)}<li class="mono">{folder}</li>{/each}</ul>{#if preview.truncated}<p class="notice-warn">{t('ops.truncated')}</p>{/if}<form id="import-volume" onsubmit={e=>{e.preventDefault();register();}}><label>{t('ops.name')}<input class="field" bind:value={name} pattern={'[A-Za-z][A-Za-z0-9\\-]{0,11}'} maxlength="12" required/></label><label>{t('ops.confirmName',{name})}<input class="field mono" bind:value={confirm} required/></label></form>{#if error}<p class="notice-error">{error}</p>{/if}<div class="dialog-actions"><button class="btn" disabled={busy} onclick={()=>preview=null}>{t('common.cancel')}</button><button form="import-volume" class="btn btn-warn" disabled={busy||!name||confirm!==name}>{t('ops.register')}</button></div></Dialog>{/if}
{:else}<p class="notice-error">{t('error.forbidden')}</p>{/if}
<style>.candidates{padding:var(--tile-pad);margin-top:var(--gap)}article{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px;padding:16px 0;border-bottom:1px solid var(--border)}article p{overflow-wrap:anywhere;font-size:.85rem}article div{min-width:0}label{display:flex;flex-direction:column;gap:6px;margin-top:14px;font-size:.85rem}li{overflow-wrap:anywhere}</style>
